/**
 * codegen-oracle probe (P-2026-10-10-2029): the two lecture examples of codegen/examples/ in the app, generated by the
 * Code panel and checked by the oracle against the simulator (R-GEN-11, R-GEN-15, R-GEN-16 provisional).
 *
 * Fresh context, Advanced mode, the experimental setting on (its localStorage key, written before the app loads).
 * For each example:
 *   - its demo scene is imported (`fixture.scene`, frontend/scripts/probe/fixtures/); the turnstile is the scene's
 *     own model, the producer-consumer a new model of the scene's metamodel (the «New model» function, `createM1`)
 *     built by the example's JjScript, one command at a time at M1, as the README tells a student;
 *   - the example is installed by name: the fixture's metamodel bag (roles and `genTemplates`) and model bag
 *     (declarations) are written with the `state` setter, every fixture id replaced by the app's id of the element
 *     of the same name, and the scenario stored in the model's `runScenarios` the same way;
 *   - the app's model is the fixture's: every object with its class and its slots, references by name;
 *   - the Code panel opens from its pill, the Output tab generates with no error, and its crop is taken;
 *   - the oracle runs through `window.__jjodelOracle` (oracle.ts, installed with the setting on, once the panel's
 *     chunk is loaded) over the scenario stored on the model: it passes;
 *   - the program with the target of one transition swapped (the README's mutation): the oracle reports the step
 *     the fixture names, the transition, and generated text whose origin is that transition.
 *   - the program names elements, not ids (R-GEN-17, P-2026-10-11-1052): its `$ID` table holds every object of the
 *     app's model and the model itself once, and no id of the model (objects, slots, the model) appears outside it.
 *
 *   - «Run» returns `main()`'s trace (its timeout raised to 60000 ms: in dev the worker's first load counts, S4's ticket);
 *
 * Crops, light theme, in ~/.jjodel-lanes/P-2026-10-10-2029/crops/ (CGO_CROPS overrides): <example>_output.png (the top
 * of the Output tab), <example>_ids.png (scrolled to the `$ID` table) and <example>_transitions.png (scrolled to the
 * transition table), with their sizes printed.
 *
 * Run:  ~/.local/bin/node frontend/scripts/lane-run.mjs probe <worktree> frontend/scripts/probe/codegen-oracle.ts \
 *         --port 3089 --id P-2026-10-10-2029
 * Env:  CGO_EXAMPLE  one example name (default: both)
 *       CGO_OUT      JSON output (default frontend/scripts/smoke/_tmp_codegen-oracle.json, gitignored)
 *       CGO_CROPS    the crops' folder (default ~/.jjodel-lanes/P-2026-10-10-2029/crops)
 */
import { chromium, type Page } from '@playwright/test';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { seed } from '../smoke/states.ts';

const URL = (process.env.PROBE_URL || 'http://localhost:3089/').replace(/\/$/, '');
if (/:(3000|3001|3003)$/.test(URL)) throw new Error('never 3000, 3001 or 3003');
const OUT = process.env.CGO_OUT || new globalThis.URL('../smoke/_tmp_codegen-oracle.json', import.meta.url).pathname;
const CROPS = process.env.CGO_CROPS || `${homedir()}/.jjodel-lanes/P-2026-10-10-2029/crops`;
const NAMES = process.env.CGO_EXAMPLE ? [process.env.CGO_EXAMPLE] : ['turnstile', 'petri-producer-consumer'];
mkdirSync(CROPS, { recursive: true });

interface Example {
    name: string;
    scene: string;
    lookup: Record<string, any>;
    jjscript?: string[];
    scenario: { name: string; steps: Array<{ event: string | null; selector: string | null; kind: string }>; expect?: string };
    mutation: { transition: string; from: string; to: string; step: number };
}

const example = (name: string): Example => JSON.parse(readFileSync(new globalThis.URL(`../../src/codegen/examples/${name}/${name}.json`, import.meta.url), 'utf8'));
const scene = (name: string) => new globalThis.URL(`./fixtures/${name}.jjodel`, import.meta.url).pathname;

const note = (label: string, d: unknown) => console.log(`MEAS  ${label}  ${typeof d === 'string' ? d : JSON.stringify(d)}`);
let failures = 0;
const check = (label: string, ok: boolean, detail: unknown) => {
    if (!ok) failures++;
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}  ${typeof detail === 'string' ? detail : JSON.stringify(detail)}`);
};
const wait = (page: Page, ms: number) => page.waitForTimeout(ms);

async function poll<T>(page: Page, expr: string, ms: number): Promise<T | null> {
    const end = Date.now() + ms;
    while (Date.now() < end) {
        const v = await page.evaluate(expr).catch(() => null) as T | null;
        if (v) return v;
        await wait(page, 250);
    }
    return null;
}

async function crop(page: Page, file: string, box: { x: number; y: number; w: number; h: number }, pad = 8) {
    const vp = page.viewportSize() ?? { width: 1600, height: 1000 };
    const x = Math.max(0, Math.floor(box.x - pad));
    const y = Math.max(0, Math.floor(box.y - pad));
    const width = Math.min(vp.width - x, Math.ceil(box.w + 2 * pad));
    const height = Math.min(vp.height - y, Math.ceil(box.h + 2 * pad));
    await page.screenshot({ path: `${CROPS}/${file}`, clip: { x, y, width, height } });
    console.log(`CROP  ${CROPS}/${file}  ${width}x${height}`);
}

// ── Page side (plain strings: no transform) ────────────────────────────────────────────────────

const IMPORT = (text: string) => String.raw`(async () => {
  const api = await import('/src/api/persistance/projects.ts');
  const count = () => JSON.parse(localStorage.getItem('projects') || '[]').length;
  const before = count();
  await api.ProjectsApi.importFromText(${JSON.stringify(text)});
  for (let i = 0; i < 75 && count() <= before; i++) await new Promise(r => setTimeout(r, 200));
  const a = JSON.parse(localStorage.getItem('projects') || '[]');
  return a.length > before ? a[a.length - 1].id : null;
})()`;

/** The metamodel by name, and the model by name when given; `null` until loaded. */
const LOADED = (mm: string, m1: string | null) => String.raw`(() => {
  try {
    const all = Object.values(window.windoww.store.getState().idlookup).filter((d) => d && typeof d === 'object');
    const a = all.find((d) => d.className === 'DModel' && d.isMetamodel && d.name === ${JSON.stringify(mm)});
    const b = ${JSON.stringify(m1)} === null ? null : all.find((d) => d.className === 'DModel' && !d.isMetamodel && d.name === ${JSON.stringify(m1)});
    if (!a || document.querySelectorAll('.dock-tab').length === 0) return null;
    if (${JSON.stringify(m1)} !== null && !b) return null;
    return { mm: a.id, m1: b ? b.id : null };
  } catch (e) { return null; }
})()`;

/** A new model of the project's metamodel, through the function the «New model» entry calls (jjscript-m1 probe). */
const NEW_MODEL = String.raw`(async () => {
  const j = await import('/src/joiner/index.ts');
  const nav = await import('/src/pages/components/Navbar.tsx');
  const p = j.L.fromPointer(j.DUser.current).project;
  const before = new Set((p.models || []).map((m) => m.id));
  nav.createM1(p, p.metamodels[0], false);
  for (let i = 0; i < 50; i++) {
    await new Promise((r) => setTimeout(r, 100));
    const m = (j.L.fromPointer(j.DUser.current).project.models || []).find((m) => !before.has(m.id) && !m.isMetamodel);
    if (m) return { id: m.id, name: m.name };
  }
  return null;
})()`;

/** The example's JjScript at M1, one command at a time, as Jjodie's Run calls the service per line. */
const JJSCRIPT = (lines: string[], mm: { id: string; name: string }, m1: string) => String.raw`(async () => {
  const svc = await import('/src/jjscript/services/JjScriptService.ts');
  const ev = await import('/src/events/registry.ts');
  window.dispatchEvent(new CustomEvent(ev.JjScriptEvents.EXECUTION_START, { detail: { script: '', mode: 'run-all', commandCount: 0 } }));
  const scope = { level: 'M1', metamodelId: ${JSON.stringify(mm.id)}, metamodelName: ${JSON.stringify(mm.name)}, modelId: ${JSON.stringify(m1)} };
  const failed = [];
  for (const line of ${JSON.stringify(lines)}) {
    const r = await svc.JjScriptService.execute(line, scope);
    if (!r.success) failed.push(line + ' -> ' + r.message);
    await new Promise((r) => setTimeout(r, 150));
  }
  return failed;
})()`;

/**
 * The fixture's ids as the app's, by name: the metamodel MM and the model M, the classes of the metamodel, their
 * features by class and name, the objects of the model. Then the example is written with the `state` setter.
 */
const INSTALL = (ex: Example, ids: { mm: string; m1: string }) => String.raw`(async () => {
  const fx = ${JSON.stringify(ex.lookup)};
  const scenario = ${JSON.stringify(ex.scenario)};
  const SC = await import('/src/model/simulation/scenarioCodec.ts');
  const lk = () => window.windoww.store.getState().idlookup;
  const L = (x) => window.LPointerTargetable.fromPointer(x);
  const mmId = ${JSON.stringify(ids.mm)}, m1Id = ${JSON.stringify(ids.m1)};
  const under = (id, root) => { let d = lk()[id]; for (let i = 0; d && i < 40; i++) { if (d.id === root) return true; d = lk()[d.father]; } return false; };
  const all = Object.values(lk()).filter((d) => d && typeof d === 'object');
  const map = { MM: mmId, M: m1Id };
  const missing = [];
  for (const [fid, d] of Object.entries(fx)) {
    if (d.className === 'DClass') {
      const c = all.find((x) => x.className === 'DClass' && x.name === d.name && under(x.id, mmId));
      if (c) map[fid] = c.id; else missing.push(fid);
    }
  }
  for (const [fid, d] of Object.entries(fx)) {
    if (d.className === 'DAttribute' || d.className === 'DReference') {
      const f = all.find((x) => x.className === d.className && x.name === d.name && x.father === map[d.father]);
      if (f) map[fid] = f.id; else missing.push(fid);
    }
    if (d.className === 'DObject') {
      const o = all.find((x) => x.className === 'DObject' && x.name === d.name && under(x.id, m1Id));
      if (o) map[fid] = o.id; else missing.push(fid);
    }
  }
  const remap = (v) => (typeof v === 'string' && Object.prototype.hasOwnProperty.call(map, v) ? map[v] : v);
  L(mmId).state = { simEnabled: true };
  await new Promise((r) => setTimeout(r, 300));
  const bag = {};
  for (const [k, v] of Object.entries(fx.MM._state)) if (k !== 'simEnabled') bag[k] = remap(v);
  L(mmId).state = bag;
  await new Promise((r) => setTimeout(r, 300));
  const own = fx.M._state || {};
  if (Object.keys(own).length > 0) { L(m1Id).state = { ...own }; await new Promise((r) => setTimeout(r, 300)); }
  const stored = { ...scenario, steps: scenario.steps.map((s) => ({ ...s, event: remap(s.event), selector: remap(s.selector) })) };
  L(m1Id).state = { [SC.RUN_SCENARIOS_KEY]: SC.encodeScenarios([stored]) };
  await new Promise((r) => setTimeout(r, 300));
  // The model as the fixture says it: per object its class and its slots, ids read back as fixture ids.
  const back = Object.fromEntries(Object.entries(map).map(([f, a]) => [a, f]));
  const shape = (look, model, name) => {
    const out = {};
    for (const o of Object.values(look).filter((x) => x && x.className === 'DObject' && (model === null || under(x.id, model)))) {
      const slots = {};
      for (const vid of o.features || []) {
        const v = look[vid];
        const f = v && look[v.instanceof];
        if (!f) continue;
        const values = (v.values || []).filter((x) => x !== null && x !== undefined).map((x) => (typeof x === 'string' && look[x] && look[x].className === 'DObject' ? look[x].name : x));
        if (values.length > 0) slots[f.name] = values;
      }
      out[o.name] = { class: look[o.instanceof] && look[o.instanceof].name, slots };
    }
    return out;
  };
  return { map, missing, app: shape(lk(), m1Id), fixture: shape(fx, null) };
})()`;

const PANE = (m1Id: string) => `(document.querySelector('[role="tabpanel"][aria-labelledby$="-tab-${m1Id}"]'))`;
const CLICK = (expr: string) => String.raw`(() => { const el = ${expr}; if (!el) return { found: false }; el.click(); return { found: true }; })()`;
const BOX = (expr: string) => String.raw`(() => { const el = ${expr}; if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; })()`;

/**
 * The oracle through its hook; `swap` is the README's mutation, written in the page over the program's `$ID` table
 * (R-GEN-17): the entry found by `id: $ID.<name>`, the place by `place: $ID.<name>`, the names read from the table.
 * Without a swap the generated text comes back too, for the scan of ids.
 */
const ORACLE = (m1Id: string, swap: { transition: string; from: string; to: string } | null) => String.raw`(async () => {
  const swap = ${JSON.stringify(swap)};
  const mutate = swap === null ? undefined : (code) => {
    const start = code.indexOf('const $ID = Object.freeze({');
    const close = start < 0 ? -1 : code.indexOf('\n});', start);
    const table = close < 0 ? {} : new Function(code.slice(start, close + 4) + '\nreturn $ID;')();
    const names = new Map(Object.entries(table).map(([n, id]) => [id, n]));
    const ref = (id) => '$ID.' + (names.has(id) ? names.get(id) : id);
    const at = code.indexOf('id: ' + ref(swap.transition) + ',');
    const post = code.indexOf('postset: [', at);
    const end = code.indexOf(']', post);
    const segment = code.slice(post, end);
    const swapped = segment.replace('place: ' + ref(swap.from) + ',', 'place: ' + ref(swap.to) + ',');
    if (at < 0 || swapped === segment) throw new Error('mutation: no postset place ' + swap.from + ' in ' + swap.transition);
    return code.slice(0, post) + swapped + code.slice(end);
  };
  const r = await window.__jjodelOracle.run({ modelId: ${JSON.stringify(m1Id)}, timeoutMs: 60000, mutate });
  const { code, sim, gen, ...rest } = r;
  return { ...rest, sim: (sim || []).map((s) => s.kind), gen: (gen || []).map((s) => s.kind), lines: typeof code === 'string' ? code.split('\n').length : 0, ...(swap === null && typeof code === 'string' ? { code } : {}) };
})()`;

/** The ids of the app's model: the model, and every entry whose father chain reaches it, with its class. */
const MODEL_IDS = (m1Id: string) => String.raw`(() => {
  const lk = window.windoww.store.getState().idlookup;
  const under = (id) => { let d = lk[id]; for (let i = 0; d && i < 40; i++) { if (d.id === ${JSON.stringify(m1Id)}) return true; d = lk[d.father]; } return false; };
  return Object.keys(lk).filter((id) => lk[id] && typeof lk[id] === 'object' && under(id)).map((id) => ({ id, className: lk[id].className }));
})()`;

/** The occurrences of `id` in `text` as a whole token: an id that is a prefix of another (`_USER_4`, `_USER_48`) is not counted in it. */
function occurrences(text: string, id: string): number {
    const esc = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return (text.match(new RegExp(`(?<![A-Za-z0-9_])${esc}(?![A-Za-z0-9_])`, 'g')) ?? []).length;
}

// ── Main ──────────────────────────────────────────────────────────────────────────────────────

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
await ctx.addInitScript(() => { (globalThis as any).__name = (f: any) => f; });
await seed(ctx, true);
await ctx.addInitScript(() => { localStorage.setItem('jjodel.experimental.codegen', 'true'); });
const page = await ctx.newPage();
const errors: string[] = [];
page.on('pageerror', (e: Error) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text().slice(0, 200)); });
const result: Record<string, any> = { url: URL, examples: {} };

for (const name of NAMES) {
    const ex = example(name);
    const r: Record<string, any> = {};
    result.examples[name] = r;
    const mmName = ex.lookup.MM.name as string;
    const m1Name = ex.jjscript ? null : (ex.lookup.M.name as string);

    await page.goto(`${URL}/#/allProjects`, { waitUntil: 'domcontentloaded', timeout: 300000 });
    await poll(page, `!!(window.windoww && window.windoww.store && window.LPointerTargetable)`, 120000);
    await wait(page, 2000);
    const pid = await page.evaluate(IMPORT(readFileSync(scene(ex.scene), 'utf8'))) as string | null;
    check(`${name}: the scene ${ex.scene} is imported`, !!pid, String(pid));
    if (!pid) continue;
    await page.goto(`${URL}/?open=${encodeURIComponent(pid)}#/project?id=${pid}`, { waitUntil: 'domcontentloaded', timeout: 300000 });
    const loaded = await poll<{ mm: string; m1: string | null }>(page, LOADED(mmName, m1Name), 120000);
    check(`${name}: the project loads`, !!loaded, JSON.stringify(loaded));
    if (!loaded) continue;
    await wait(page, 3000);

    let m1 = loaded.m1;
    if (ex.jjscript) {
        const created = await page.evaluate(NEW_MODEL) as { id: string; name: string } | null;
        check(`${name}: a new model of ${mmName}`, !!created, JSON.stringify(created));
        if (!created) continue;
        m1 = created.id;
        const failed = await page.evaluate(JJSCRIPT(ex.jjscript, { id: loaded.mm, name: mmName }, m1)) as string[];
        r.jjscript = { lines: ex.jjscript.length, failed };
        check(`${name}: the JjScript of the README builds the model (${ex.jjscript.length} commands)`, failed.length === 0, failed.slice(0, 5));
        await wait(page, 1500);
    }
    if (!m1) continue;

    const installed = await page.evaluate(INSTALL(ex, { mm: loaded.mm, m1 })) as any;
    r.map = installed.map;
    check(`${name}: every element of the fixture has its namesake in the app`, installed.missing.length === 0, installed.missing);
    check(`${name}: the app's model is the fixture's, object by object`, JSON.stringify(sortKeys(installed.app)) === JSON.stringify(sortKeys(installed.fixture)),
        { app: Object.keys(installed.app).length, fixture: Object.keys(installed.fixture).length });
    const appId = (fid: string) => installed.map[fid] ?? fid;

    // The model's editor, then the Code panel from its pill.
    await page.evaluate(String.raw`(async () => { const dm = await import('/src/components/abstract/DockManager.tsx'); await dm.default.open2(window.LPointerTargetable.fromPointer(${JSON.stringify(m1)})); })()`);
    const pane = PANE(m1);
    await poll(page, `(() => { const p = ${pane}; return !!p && p.querySelectorAll('.react-flow__node').length > 0; })()`, 60000);
    await wait(page, 2000);
    const pill = await poll(page, `!!(${pane} && ${pane}.querySelector('.codegen-pill button'))`, 30000);
    check(`${name}: the Code pill is on the model's editor`, !!pill, '');
    await page.evaluate(CLICK(`${pane}.querySelector('.codegen-pill button')`));
    const panel = `${pane}.querySelector('.codegen-panel')`;
    check(`${name}: the pill opens the panel`, !!(await poll(page, `!!(${panel})`, 60000)), '');
    await page.evaluate(CLICK(`[...${panel}.querySelectorAll('.codegen-panel__tab')].find((b) => b.textContent.trim() === 'Output')`));
    await poll(page, `!!(${panel}.querySelector('.codegen-panel__code'))`, 30000);
    await wait(page, 500);
    const out = await page.evaluate(String.raw`(() => {
      const p = ${panel};
      const lines = [...p.querySelectorAll('.codegen-panel__line')].map((l) => l.querySelector('.codegen-panel__text').textContent);
      return { lines: lines.length, first: lines[0] || '', errors: [...p.querySelectorAll('.codegen-panel__error')].map((e) => e.textContent.trim()), exports: lines.filter((l) => l.startsWith('export function')).map((l) => l.replace(/\(.*$/, '')) };
    })()`) as any;
    r.output = out;
    note(`${name}: output`, out);
    check(`${name}: Generate gives the program with no error`, out.errors.length === 0 && out.lines > 100, out.errors.slice(0, 3));
    check(`${name}: the program exports initial, step, observe and main`,
        ['export function initial', 'export function step', 'export function observe', 'export function main'].every(e => out.exports.includes(e)), out.exports);
    const pBox = await page.evaluate(BOX(panel)) as any;
    if (pBox) await crop(page, `${name}_output.png`, pBox);
    // A line of the program scrolled to the top of the code area.
    const scrollTo = (text: string) => page.evaluate(String.raw`(() => {
      const p = ${panel};
      const pre = p.querySelector('.codegen-panel__code');
      const line = [...p.querySelectorAll('.codegen-panel__line')].find((l) => l.textContent.includes(${JSON.stringify(text)}));
      if (!pre || !line) return null;
      pre.scrollTop = line.offsetTop - pre.offsetTop;
      return { scrollTop: pre.scrollTop, line: line.getAttribute('data-line') };
    })()`);
    // The table of element ids (R-GEN-17), then the transition table: the parts of the program the model shaped.
    const idsAt = await scrollTo('const $ID = Object.freeze({');
    check(`${name}: the $ID table is in the output`, !!idsAt, JSON.stringify(idsAt));
    await wait(page, 300);
    if (pBox) await crop(page, `${name}_ids.png`, pBox);
    const scrolled = await scrollTo('One entry per transition');
    check(`${name}: the transition table is in the output`, !!scrolled, JSON.stringify(scrolled));
    await wait(page, 300);
    if (pBox) await crop(page, `${name}_transitions.png`, pBox);

    // «Run» calls main(): the timeout raised for the dev server's first worker (the S4 ticket, lane P-2026-10-10-2027).
    await page.locator(`.codegen-panel__timeout input`).fill('60000');
    await page.evaluate(CLICK(`${panel}.querySelector('.codegen-panel__run .codegen-panel__button--primary')`));
    const ran = await poll<any>(page, String.raw`(() => {
      const p = ${panel};
      const ok = p.querySelector('.codegen-panel__result:not(.codegen-panel__result--error) .codegen-panel__value');
      const bad = p.querySelector('.codegen-panel__result--error');
      if (ok) return { ok: true, value: JSON.parse(ok.textContent) };
      if (bad) return { ok: false, error: bad.textContent.trim() };
      return null;
    })()`, 90000);
    r.run = ran;
    note(`${name}: Run`, ran);
    check(`${name}: Run returns main()'s trace, starting at the initial state`, !!ran && ran.ok === true && Array.isArray(ran.value) && ran.value.length > 1 && ran.value[0].step === 0, JSON.stringify(ran).slice(0, 300));

    // The oracle, through the hook the panel's chunk installed.
    const hook = await poll(page, `!!(window.__jjodelOracle && window.__jjodelOracle.run)`, 30000);
    check(`${name}: the oracle hook is installed with the setting on`, !!hook, '');
    const { code: program, ...pass } = await page.evaluate(ORACLE(m1, null)) as any;
    r.pass = pass;
    note(`${name}: oracle`, pass);
    // R-GEN-17: every id of the app's model once, in the $ID block, and nowhere else.
    const modelIds = await page.evaluate(MODEL_IDS(m1)) as Array<{ id: string; className: string }>;
    const text = typeof program === 'string' ? program : '';
    const blockStart = text.indexOf('const $ID = Object.freeze({');
    const blockEnd = blockStart < 0 ? -1 : text.indexOf('\n});', blockStart) + 4;
    const block = blockEnd > blockStart ? text.slice(blockStart, blockEnd) : '';
    const outside = blockEnd > blockStart ? text.slice(0, blockStart) + text.slice(blockEnd) : text;
    const named = modelIds.filter(x => x.className === 'DObject' || x.className === 'DModel');
    const notOnce = named.filter(x => block.split(`'${x.id}'`).length - 1 !== 1).map(x => x.id);
    const leaked = modelIds.filter(x => occurrences(outside, x.id) > 0).map(x => x.id);
    r.ids = { model: modelIds.length, named: named.length, notOnce, leaked, declarations: text.split('const $ID = Object.freeze({').length - 1, refs: text.split('$ID.').length - 1 };
    note(`${name}: ids`, r.ids);
    check(`${name}: the program declares $ID once, with the model and every object of it once (${named.length})`,
        r.ids.declarations === 1 && named.length > 5 && notOnce.length === 0, { notOnce: notOnce.slice(0, 5) });
    check(`${name}: no id of the model outside the $ID block (${modelIds.length} ids scanned)`, modelIds.length > named.length && leaked.length === 0 && r.ids.refs > 10, { leaked: leaked.slice(0, 5) });
    check(`${name}: the oracle passes on the scenario «${ex.scenario.name}» (${ex.scenario.steps.length} steps)`,
        pass.ok === true && pass.gen.length === ex.scenario.steps.length + 1, JSON.stringify(pass).slice(0, 400));
    const m = ex.mutation;
    const mutated = await page.evaluate(ORACLE(m1, { transition: appId(m.transition), from: appId(m.from), to: appId(m.to) })) as any;
    r.mutated = mutated;
    note(`${name}: oracle, ${m.transition} swapped to ${m.to}`, mutated);
    check(`${name}: the swapped target is reported at step ${m.step}, transition ${m.transition}, with its generated text`,
        mutated.ok === false && mutated.kind === 'observe' && mutated.step === m.step && mutated.transitionId === appId(m.transition)
        && mutated.origin?.origin?.elementId === appId(m.transition), JSON.stringify(mutated).slice(0, 400));
}

const own = errors.filter(e => /codegen|oracle|jjodelOracle/i.test(e));
result.errors = errors;
note('console errors', { total: errors.length, codegen: own.length });
check('no console error from the generator or the oracle', own.length === 0, own.slice(0, 5));
writeFileSync(OUT, JSON.stringify(result, null, 1));
console.log(`${failures === 0 ? 'ALL GREEN' : `${failures} FAILED`}  (${OUT})`);
await browser.close();
process.exit(failures === 0 ? 0 : 1);

function sortKeys(v: any): any {
    if (Array.isArray(v)) return v.map(sortKeys);
    if (v && typeof v === 'object') return Object.fromEntries(Object.keys(v).sort().map(k => [k, sortKeys(v[k])]));
    return v;
}
